import java.util.*;
import java.util.stream.*;

public class Tour {
    record Point(int x, int y) {}                          // Java 16
    sealed interface Shape permits Circle, Square {}       // Java 17
    record Circle(double r) implements Shape {}
    record Square(double side) implements Shape {}

    static double area(Shape s) {
        return switch (s) {                                // exhaustive, no default
            case Circle c -> Math.PI * c.r() * c.r();
            case Square q -> q.side() * q.side();
        };
    }

    static String describe(Object o) {                     // pattern switch: Java 21
        return switch (o) {
            case Point(int x, int y) when x == y -> "diagonal point " + x;
            case Point p -> "point " + p;
            case String s -> "string of length " + s.length();
            case null -> "null!";
            default -> "something else";
        };
    }

    public static void main(String[] args) {
        // Java 8: streams
        System.out.println(Stream.of("b", "a", "c").sorted().collect(Collectors.joining(",")));
        // Java 9: collection factories
        List<Integer> nums = List.of(1, 2, 3);
        System.out.println(nums + " " + Map.of("k", 1));
        // Java 10: var
        var names = new ArrayList<String>();
        names.add("Asha");
        System.out.println(names);
        // Java 11: new String methods
        System.out.println("  hi ".strip() + "|" + "ab".repeat(3) + "|" + " ".isBlank());
        // Java 14: switch expression
        int day = 3;
        String kind = switch (day) { case 6, 7 -> "weekend"; default -> "weekday"; };
        System.out.println(kind);
        // Java 15: text block
        String json = """
            {"id": 1,
             "name": "Asha"}
            """;
        System.out.print(json);
        // Java 16: pattern variable in instanceof, record, Stream.toList()
        Object o = "hello";
        if (o instanceof String s && s.length() > 3) System.out.println(s.toUpperCase());
        System.out.println(new Point(1, 2));
        System.out.println(Stream.of(1, 2, 3, 4).filter(n -> n % 2 == 0).toList());
        // Java 21: pattern matching for switch, record patterns, guards
        System.out.println(describe(new Point(2, 2)) + "; " + describe(new Point(1, 2))
            + "; " + describe("abc") + "; " + describe(null) + "; " + describe(4));
        System.out.printf("%.2f%n", area(new Circle(1)));
        // Java 21: sequenced collections
        var seq = new ArrayList<>(List.of(1, 2, 3));
        System.out.println(seq.getFirst() + " " + seq.getLast() + " " + seq.reversed());
        // Java 21: virtual threads
        try (var ex = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {
            System.out.println(ex.submit(() -> Thread.currentThread().isVirtual()).get());
        } catch (Exception e) { throw new RuntimeException(e); }
    }
}

