import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class AccountTest {
    private Account account;

    @BeforeEach
    void setUp() {                       // runs before EACH test, on a fresh test instance
        account = new Account();
    }

    @Test
    @DisplayName("deposits add up")
    void depositIncreasesBalance() {
        account.deposit(50);
        account.deposit(25);
        assertEquals(75L, account.balance());
    }

    @Test
    void depositRejectsZero() {
        var ex = assertThrows(IllegalArgumentException.class, () -> account.deposit(0));
        assertEquals("amount must be positive", ex.getMessage());
    }

    @ParameterizedTest
    @ValueSource(longs = {-1, 0, -100})
    void depositRejectsNonPositive(long amount) {
        assertThrows(IllegalArgumentException.class, () -> account.deposit(amount));
    }

    @Test
    void severalChecksAtOnce() {
        assertAll(
            () -> assertEquals(0L, account.balance()),
            () -> assertTrue(account.balance() >= 0));
    }

    @AfterEach void tearDown() { /* release resources */ }
}

import java.lang.annotation.*;
import java.lang.reflect.*;

public class MiniTest {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD)
    @interface Test {}

    static class Account {
        private long balance;
        void deposit(long amount) {
            if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
            balance += amount;
        }
        long balance() { return balance; }
    }

    static class AccountTests {
        @Test void depositIncreasesBalance() {
            var a = new Account();
            a.deposit(50);
            a.deposit(25);
            assertEquals(75L, a.balance());
        }
        @Test void depositRejectsZero() {
            assertThrows(IllegalArgumentException.class, () -> new Account().deposit(0));
        }
        @Test void deliberatelyBroken() {
            assertEquals(1L, new Account().balance());
        }
    }

    static void assertEquals(Object expected, Object actual) {
        if (!expected.equals(actual))
            throw new AssertionError("expected <" + expected + "> but was <" + actual + ">");
    }
    static void assertThrows(Class<? extends Throwable> type, Runnable code) {
        try { code.run(); }
        catch (Throwable t) {
            if (type.isInstance(t)) return;
            throw new AssertionError("expected " + type.getSimpleName() + " but got " + t);
        }
        throw new AssertionError("expected " + type.getSimpleName() + " but nothing was thrown");
    }

    public static void main(String[] args) throws Exception {
        int passed = 0, failed = 0;
        for (Method m : AccountTests.class.getDeclaredMethods()) {
            if (!m.isAnnotationPresent(Test.class)) continue;
            // a fresh instance per test, like JUnit
            Object instance = AccountTests.class.getDeclaredConstructor().newInstance();
            m.setAccessible(true);
            try {
                m.invoke(instance);
                passed++;
                System.out.println("PASS " + m.getName());
            } catch (InvocationTargetException e) {
                failed++;
                System.out.println("FAIL " + m.getName() + " -> " + e.getCause().getMessage());
            }
        }
        System.out.println(passed + " passed, " + failed + " failed");
        if (failed > 0) System.exit(1);
    }
}

import java.time.*;

public class Cl {
    record Subscription(LocalDate end) {
        boolean expired(Clock clock) {
            return LocalDate.now(clock).isAfter(end);
        }
    }

    public static void main(String[] a) {
        var s = new Subscription(LocalDate.of(2026, 1, 31));
        var before = Clock.fixed(Instant.parse("2026-01-31T10:00:00Z"), ZoneOffset.UTC);
        var after = Clock.fixed(Instant.parse("2026-02-01T00:00:01Z"), ZoneOffset.UTC);
        System.out.println(s.expired(before) + " " + s.expired(after));
    }
}

