class Person {
    protected final int age;
    Person(int age) {
        this.age = age;
        describe();                      // may call an overridden method!
    }
    void describe() { System.out.println("Person " + age); }
}
class Employee extends Person {
    private final String officeId;

    Employee(int age, String officeId) {
        if (age < 18 || age > 67)                        // prologue: fail fast
            throw new IllegalArgumentException("Age out of range: " + age);
        this.officeId = officeId;                        // prologue: assign own field
        super(age);                                      // now call the superclass constructor
    }

    @Override void describe() { System.out.println("Employee " + age + " @" + officeId); }
}

public class Sv {
    private static final ScopedValue<String> USER = ScopedValue.newInstance();

    static void handle() {
        System.out.println("user=" + (USER.isBound() ? USER.get() : "unbound"));
    }

    public static void main(String[] args) {
        handle();
        ScopedValue.where(USER, "alice").run(() -> {
            handle();
            ScopedValue.where(USER, "bob").run(Sv::handle);   // rebinding
            handle();
        });
        handle();
    }
}
